	if directory == "" || strings.ContainsAny(directory, "/\\") {
		return os.ErrInvalid
	}

	// Ensure the filename is not empty and does not contain path separators.
	if filename == "" || strings.ContainsAny(filename, "/\\") {
		return os.ErrInvalid
	}

	// Construct the full file path.
	filePath := filepath.Join(directory, filename)

	// Create the directory if it doesn't exist.
	// 0700 means read, write, and execute for owner, no permissions for group or others.
	if err := os.MkdirAll(directory, 0700); err != nil {
		return err
	}

	// Write the content to the file with permissions for the owner only.
	// 0600 means read and write for owner, no permissions for group or others.
	err := os.WriteFile(filePath, []byte(content), 0600)
	if err != nil {
		return err
	}

	return nil
}
